import numpy as np
from scipy import stats


def q094(values, confidence=0.95):
    x = np.asarray(values, float)
    half = (
        stats.t.ppf((1 + confidence) / 2, len(x) - 1)
        * x.std(ddof=1)
        / np.sqrt(len(x))
    )
    return (float(x.mean() - half), float(x.mean() + half))
